package ru.evolenta.pgs.worker;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import static ru.evolenta.pgs.worker.Util.*;

/** Server-side rollback through the platform DELETE API; the browser only records confirmation. */
public final class RollbackOperations {
    private static final List<String>COLLECTIONS=Arrays.asList("placeReestrRKCollection","nsiUnifiedPGS_object_marketing","biddingReestrRKCollection","contractReestrRKCollection","obligationReestrRKCollection","marketingLicenses","marketingRegistry","socialAdReestrRKCollection","unauthorizedReestrRKCollection","dismantleReestrRKCollection");
    private final CheckpointStore journal;private final Operations.Lease lease;private final boolean writes;private final List<Object>refFields;
    public RollbackOperations(CheckpointStore journal,Operations.Lease lease,boolean writes)throws Exception{this.journal=journal;this.lease=lease;this.writes=writes;try(InputStream in=getClass().getResourceAsStream("/advertising-reference-fields.json")){refFields=list(Json.read(in));}}
    private String targetId(Context c){Object selected=first(c.appeal.get("migrationCase"),c.xsd.get("migrationCase"),at(c.xsd,"mainElement.migrationCase"));if(selected instanceof List)selected=list(selected).isEmpty()?null:list(selected).get(0);String id=selected instanceof Map?clean(first(map(selected).get("_id"),map(selected).get("id"),map(selected).get("code"))):clean(selected);if(id.isEmpty()||id.equals(c.command.mainId))throw new IllegalArgumentException("Выберите исходное дело миграции");return id;}
    private Map<String,Object>target(Context c,String id)throws Exception{Map<String,Object>target=c.api.find(c.command.collection,id);String owner=clean(first(c.appeal.get("unitId"),at(c.appeal,"unit.id"))),targetOwner=clean(first(target.get("unitId"),at(target,"unit.id")));if(owner.isEmpty()||!owner.equals(targetOwner))throw new IllegalArgumentException("Можно выбрать только миграцию своей организации");if(!"complete".equals(at(target,"status.code")))throw new IllegalArgumentException("Откат доступен только для завершённой миграции");return target;}
    private Map<String,Object>sourceSub(Map<String,Object>target,String guid){List<Map<String,Object>>found=new ArrayList<Map<String,Object>>();for(Map<String,Object>s:maps(target.get("subservices")))if((guid.isEmpty()||guid.equals(clean(s.get("guid"))))&&ImportOperations.WORKER_CONTRACT.equals(at(s,"advertisingMigrationSummary.workerContract"))&&clean(at(s,"advertisingMigrationSummary.workerRunKey")).matches("[0-9a-f]{64}")&&"Реклама".equals(at(s,"advertisingMigrationSummary.dataType"))&&"APPLIED".equals(at(s,"advertisingMigrationSummary.status"))&&!list(s.get("migrationCreatedRecords")).isEmpty())found.add(s);if(found.size()!=1)throw new IllegalArgumentException("Откат разрешён только для нового завершённого импорта external-worker; подходящий журнал не найден однозначно");return found.get(0);}
    private List<Map<String,Object>>entries(Map<String,Object>sub){List<Map<String,Object>>out=new ArrayList<Map<String,Object>>();Set<String>seen=new HashSet<String>();for(Map<String,Object>e:maps(sub.get("migrationCreatedRecords"))){String collection=clean(e.get("collection")),id=id(e);if(!COLLECTIONS.contains(collection)||id.isEmpty()||!clean(e.get("businessHash")).matches("[0-9a-f]{64}")||!clean(e.get("operationKey")).matches("[0-9a-f]{64}"))throw new IllegalArgumentException("Некорректная запись журнала миграции");if(seen.add(collection+"/"+id))out.add(copy(e));}if(out.isEmpty()||out.size()>2500)throw new IllegalArgumentException("Журнал отката должен содержать от 1 до 2500 записей");return out;}
    private String fingerprint(List<Map<String,Object>>items){List<String>keys=new ArrayList<String>();for(Map<String,Object>e:items)keys.add(e.get("collection")+"/"+id(e));Collections.sort(keys);return sha(String.join("|",keys).getBytes(StandardCharsets.UTF_8));}
    private String identityHash(Map<String,Object>plan){List<Object>identities=new ArrayList<Object>();for(Map<String,Object>i:maps(plan.get("items")))identities.add(obj("collection",i.get("collection"),"_id",i.get("_id"),"guid",i.get("guid"),"businessHash",i.get("businessHash"),"sourceKey",i.get("sourceKey")));identities.sort(Comparator.comparing(i->clean(map(i).get("collection"))+"/"+clean(map(i).get("_id"))));return hash(obj("rollbackAppealId",plan.get("rollbackAppealId"),"targetAppealId",plan.get("targetAppealId"),"targetSubserviceGuid",plan.get("targetSubserviceGuid"),"journalFingerprint",plan.get("journalFingerprint"),"items",identities));}
    public Map<String,Object>prepare(Context c)throws Exception{
        String id=targetId(c);Map<String,Object>target=target(c,id);if(present(at(target,"migrationRollback.completedAt")))throw new IllegalArgumentException("Миграция уже полностью откачена");Map<String,Object>source=sourceSub(target,"");List<Map<String,Object>>entries=entries(source),items=new ArrayList<Map<String,Object>>();
        for(Map<String,Object>entry:entries){lease.check();String collection=clean(entry.get("collection"));Map<String,Object>record=c.api.find(collection,id(entry));String state="READY",reason="";if(record.isEmpty()){state="DELETED";reason="Запись уже отсутствует в реестре";}else if((!id.equals(clean(at(record,"migrationSource.appealId")))||!ImportOperations.WORKER_CONTRACT.equals(at(record,"migrationSource.workerContract"))||!clean(entry.get("operationKey")).equals(clean(at(record,"migrationSource.operationKey"))))){state="BLOCKED";reason="Запись не принадлежит выбранной миграции";}else if(present(entry.get("businessHash"))&&!entry.get("businessHash").equals(ImportOperations.businessHash(record))){state="BLOCKED";reason="Запись изменена после завершения импорта";}
            items.add(obj("collection",collection,"_id",id(entry),"guid",record.get("guid"),"recordName",name(collection,record),"state",state,"reason",reason,"activeCases",new ArrayList<Object>(),"businessHash",record.isEmpty()?"":ImportOperations.businessHash(record),"sourceKey",clean(at(record,"migrationSource.sheetCode"))+":"+clean(at(record,"migrationSource.rowNumber")),"unitId",at(record,"unit.id")));
        }
        markReferences(c,items,items);propagate(items);String started=now();Map<String,Object>plan=obj("version","rbu-advertising-rollback-1.0","status","PREPARED","createdAt",started,"startedAt",started,"rollbackAppealId",c.command.mainId,"rollbackAppealNumber",c.appeal.get("number"),"targetAppealId",id,"targetAppealNumber",target.get("number"),"targetSubserviceGuid",source.get("guid"),"sourceFileName",first(at(target,"importDraft.file.originalName"),at(source,"rbuImportDraft.file.originalName"),at(target,"importFile.originalName")),"dataType","Реклама","journalFingerprint",fingerprint(entries),"items",items,"deletionMode","platform-delete","lastCompletedBatch",0,"resumeCount",0,"isCompleted",false);counts(plan);String key=hash(obj("process",c.command.processId,"rollback",c.command.mainId,"target",id,"journal",plan.get("journalFingerprint")));plan.put("workerPlanKey",key);journal.save(key,obj("processId",c.command.processId,"planHash",identityHash(plan),"plan",plan));Map<String,Object>confirmation=obj("header","Вторичное подтверждение удаления","migrationNumber",plan.get("targetAppealNumber"),"sourceFileName",plan.get("sourceFileName"),"dataType","Реклама","totalRecords",plan.get("totalRecords"),"deletableRecords",plan.get("deletableRecords"),"blockedRecords",plan.get("blockedRecords"),"warningText","Будет удалено записей: "+plan.get("deletableRecords")+". Операция необратима.","confirmFinalRollback",false);List<Object>rows=new ArrayList<Object>();for(Map<String,Object>i:items)rows.add(obj("collection",i.get("collection"),"recordName",i.get("recordName"),"recordId",i.get("_id"),"status",i.get("state").equals("READY")?"Будет удалена":i.get("state").equals("DELETED")?"Уже удалена":"Не будет удалена","reason",i.get("reason")));confirmation.put("rollbackItems",rows);Map<String,Object>x=copy(c.xsd);x.put("rbuAdvertisingRollbackConfirmation",confirmation);lease.check();c.saveSub(obj("rbuRollbackPlan",plan,"xsdData",x));c.saveAppeal(obj("rollbackPreparationProgress",obj("status","PREPARED","processedRecords",items.size(),"totalRecords",items.size(),"updatedAt",now())));return obj("rbuRollbackTargetId",id,"rbuRollbackPlanFingerprint",plan.get("journalFingerprint"));
    }
    public Map<String,Object>execute(Context c)throws Exception{
        if(!writes)throw new IllegalStateException("Реестровые изменения отключены worker.writesEnabled");Map<String,Object>plan=copy(map(c.sub.get("rbuRollbackPlan")));String key=require(plan,"workerPlanKey");Map<String,Object>saved=journal.read(key);if(!c.command.processId.equals(saved.get("processId"))||!identityHash(plan).equals(saved.get("planHash")))throw new IllegalArgumentException("План отката изменён или отсутствует его серверный снимок");
        plan=copy(map(saved.get("plan")));
        Object confirmed=first(at(c.appeal,"rbuRollbackDecision.confirmed"),at(c.xsd,"rbuAdvertisingRollbackConfirmation.confirmFinalRollback"));if(!bool(confirmed))throw new IllegalArgumentException("Подтвердите необратимое удаление");if(at(c.appeal,"rbuRollbackDecision.confirmed")!=null){if(!clean(plan.get("journalFingerprint")).equals(clean(at(c.appeal,"rbuRollbackDecision.journalFingerprint")))||!clean(plan.get("targetAppealId")).equals(clean(at(c.appeal,"rbuRollbackDecision.targetAppealId"))))throw new IllegalArgumentException("Подтверждение относится к другому плану отката");}
        String targetId=clean(plan.get("targetAppealId"));Map<String,Object>target=target(c,targetId),source=sourceSub(target,clean(plan.get("targetSubserviceGuid")));if(!fingerprint(entries(source)).equals(plan.get("journalFingerprint")))throw new IllegalArgumentException("Журнал исходной миграции изменился");
        List<Map<String,Object>>items=maps(plan.get("items"));items.sort(Comparator.comparingInt(i->priority(clean(i.get("collection")))));
        for(Map<String,Object>item:items){String deleteKey=deleteKey(key,item);Map<String,Object>prior=journal.read(deleteKey);if("DELETED".equals(prior.get("status"))){item.put("state","DELETED");item.put("reason","");}}
        for(int offset=0;offset<items.size();offset+=50){List<Map<String,Object>>batch=items.subList(offset,Math.min(items.size(),offset+50));lease.check();for(Map<String,Object>item:batch){if(Arrays.asList("BLOCKED","DELETED").contains(clean(item.get("state"))))continue;Map<String,Object>record=c.api.find(clean(item.get("collection")),id(item));if(record.isEmpty()){item.put("state","DELETED");continue;}if(!targetId.equals(at(record,"migrationSource.appealId"))||!clean(item.get("businessHash")).equals(ImportOperations.businessHash(record))){item.put("state","BLOCKED");item.put("reason","Запись изменена или не принадлежит миграции");}}
            markReferences(c,batch,items);propagate(items);persist(c,plan,key,saved);
            for(Map<String,Object>item:batch){if(Arrays.asList("BLOCKED","DELETED").contains(clean(item.get("state"))))continue;lease.check();String collection=clean(item.get("collection"));Map<String,Object>record=c.api.find(collection,id(item));if(record.isEmpty()){item.put("state","DELETED");continue;}if(!clean(item.get("businessHash")).equals(ImportOperations.businessHash(record)))throw new IllegalStateException("Запись изменилась непосредственно перед DELETE");String deleteKey=deleteKey(key,item);journal.save(deleteKey,obj("status","DELETE_PENDING","collection",collection,"_id",id(item),"planKey",key));
                try{c.api.delete(collection,id(item),clean(record.get("guid")));if(!c.api.find(collection,id(item)).isEmpty())throw new IllegalStateException("Запись осталась после DELETE");journal.save(deleteKey,obj("status","DELETED","collection",collection,"_id",id(item),"planKey",key,"deletedAt",now()));item.put("state","DELETED");item.put("reason","");}
                catch(Exception e){try{if(c.api.find(collection,id(item)).isEmpty()){journal.save(deleteKey,obj("status","DELETED","collection",collection,"_id",id(item),"planKey",key,"deletedAt",now()));item.put("state","DELETED");continue;}}catch(Exception verify){e.addSuppressed(verify);}item.put("state","FAILED");item.put("reason","Техническая ошибка удаления: "+e.getClass().getSimpleName());persist(c,plan,key,saved);throw e;}
            }
            plan.put("lastCompletedBatch",offset/50+1);persist(c,plan,key,saved);
        }
        plan.put("status","EXECUTED");plan.put("executedAt",now());plan.put("isCompleted",true);persist(c,plan,key,saved);return obj("rbuRollbackStatus","EXECUTED");
    }
    private void persist(Context c,Map<String,Object>plan,String key,Map<String,Object>saved)throws Exception{counts(plan);saved.put("plan",plan);journal.save(key,saved);lease.check();c.saveSub(obj("rbuRollbackPlan",plan));}
    private String deleteKey(String key,Map<String,Object>i){return hash(obj("plan",key,"collection",i.get("collection"),"id",id(i)));}
    private int priority(String c){if(Arrays.asList("contractReestrRKCollection","obligationReestrRKCollection","marketingRegistry").contains(c))return 10;if(Arrays.asList("biddingReestrRKCollection","nsiUnifiedPGS_object_marketing").contains(c))return 20;if(Arrays.asList("placeReestrRKCollection","marketingLicenses").contains(c))return 40;return 30;}
    private void counts(Map<String,Object>plan){int ready=0,deleted=0,blocked=0,failed=0;List<Map<String,Object>>items=maps(plan.get("items"));for(Map<String,Object>i:items){String s=clean(i.get("state"));if(s.equals("READY"))ready++;if(s.equals("DELETED"))deleted++;if(s.equals("BLOCKED"))blocked++;if(s.equals("FAILED"))failed++;}plan.putAll(obj("totalRecords",items.size(),"deletableRecords",ready,"deletedRecords",deleted,"blockedRecords",blocked,"technicalErrors",failed,"processedRecords",deleted+blocked,"notDeletedRecords",items.size()-deleted,"totalBatches",(items.size()+49)/50));}
    private void propagate(List<Map<String,Object>>items){Set<String>blockedSources=new HashSet<String>();for(Map<String,Object>i:items)if("BLOCKED".equals(i.get("state"))&&!clean(i.get("sourceKey")).equals(":"))blockedSources.add(clean(i.get("sourceKey")));for(Map<String,Object>i:items)if(blockedSources.contains(clean(i.get("sourceKey")))&&!Arrays.asList("DELETED","BLOCKED").contains(clean(i.get("state")))){i.put("state","BLOCKED");i.put("reason","Связана с заблокированной записью той же строки миграции");}}
    private List<Object>values(Object value,String[]parts,int index){List<Object>out=new ArrayList<Object>();if(value instanceof List){for(Object x:list(value))out.addAll(values(x,parts,index));}else if(index==parts.length)out.add(value);else if(value instanceof Map)out.addAll(values(map(value).get(parts[index]),parts,index+1));return out;}
    private void markReferences(Context c,List<Map<String,Object>>candidates,List<Map<String,Object>>all)throws Exception{
        Map<String,List<Map<String,Object>>>tokens=new HashMap<String,List<Map<String,Object>>>();for(Map<String,Object>i:candidates)if(!Arrays.asList("DELETED","BLOCKED").contains(clean(i.get("state"))))for(Object token:Arrays.asList(i.get("_id"),i.get("guid")))if(present(token))tokens.computeIfAbsent(clean(token),k->new ArrayList<Map<String,Object>>()).add(i);if(tokens.isEmpty())return;
        List<String>allTokens=new ArrayList<String>(tokens.keySet());for(int start=0;start<allTokens.size();start+=100){List<String>chunk=allTokens.subList(start,Math.min(start+100,allTokens.size()));List<Object>ors=new ArrayList<Object>();for(Object field:refFields)ors.add(obj("field",field,"operator","in","value",chunk));Set<String>seen=new HashSet<String>();for(int page=0;page<1000;page++){lease.check();List<Map<String,Object>>cases=c.api.search("marketingAppeals",Arrays.asList(obj("orSubConditions",ors)),page,100);int added=0;for(Map<String,Object>active:cases){if(seen.add(id(active)))added++;boolean finished=bool(at(active,"status.isFinish"))||"complete".equals(at(active,"status.code"));List<Map<String,Object>>subs=maps(active.get("subservices"));if(!subs.isEmpty()&&subs.stream().allMatch(s->present(s.get("dateFinish"))&&"complete".equals(at(s,"status.code"))))finished=true;if(finished)continue;for(Object field:refFields)for(Object token:values(active,clean(field).split("\\."),0))for(Map<String,Object>item:tokens.getOrDefault(clean(token),Collections.emptyList())){item.put("state","BLOCKED");item.put("reason","Запись участвует в активных делах");List<Object>refs=list(item.get("activeCases"));String activeId=id(active);if(refs.stream().noneMatch(r->activeId.equals(map(r).get("appealId"))))refs.add(obj("collection","marketingAppeals","appealId",activeId,"number",active.get("number"),"status",at(active,"status.code")));item.put("activeCases",refs);}}
                if(cases.size()<100)break;if(added==0||page==999)throw new IllegalStateException("Не удалось безопасно проверить активные дела");}
        }
        // Propagation across the source row is done after all candidate references are known.
        propagate(all);
    }
    private String name(String c,Map<String,Object>r){String p=c.equals("placeReestrRKCollection")?"infoRK.numberRK":c.equals("nsiUnifiedPGS_object_marketing")?"RKNumber":c.equals("biddingReestrRKCollection")?"procedureInfo.noticeBlock.gisNumber":c.equals("contractReestrRKCollection")?"contract.number":c.equals("socialAdReestrRKCollection")?"infoSocialAdv.numSoc":c.equals("dismantleReestrRKCollection")?"dismantlingOrderInfo.orderNumber":c.equals("marketingRegistry")||c.equals("marketingLicenses")?"number":"infoRK.kindRK.name";return clean(first(at(r,p),"—"));}
    public Map<String,Object>finish(Context c)throws Exception{
        Map<String,Object>publicPlan=map(c.sub.get("rbuRollbackPlan"));Map<String,Object>saved=journal.read(require(publicPlan,"workerPlanKey"));if(!c.command.processId.equals(saved.get("processId")))throw new IllegalArgumentException("План другого процесса");Map<String,Object>plan=map(saved.get("plan"));if(!"EXECUTED".equals(plan.get("status")))throw new IllegalStateException("Нет исполненного плана отката");Map<String,Object>target=target(c,clean(plan.get("targetAppealId")));counts(plan);String completed=now(),status=integer(plan.get("notDeletedRecords"))==0?"ROLLED_BACK":"PARTIAL";List<Object>notDeleted=new ArrayList<Object>(),deletedKeys=new ArrayList<Object>();for(Map<String,Object>i:maps(plan.get("items")))if("DELETED".equals(i.get("state")))deletedKeys.add(i.get("collection")+"/"+id(i));else notDeleted.add(obj("rowNumber",notDeleted.size()+1,"collection",i.get("collection"),"recordId",id(i),"reason",first(i.get("reason"),"Не удалено"),"activeCases",i.get("activeCases")));Map<String,Object>report=obj("version","rbu-advertising-rollback-report-1.0","status",status,"completedAt",completed,"rollbackAppealId",c.command.mainId,"rollbackAppealNumber",c.appeal.get("number"),"targetAppealId",plan.get("targetAppealId"),"targetAppealNumber",plan.get("targetAppealNumber"),"totalRecords",plan.get("totalRecords"),"deletedRecords",plan.get("deletedRecords"),"notDeletedRecords",plan.get("notDeletedRecords"),"blockedRecords",plan.get("blockedRecords"),"technicalErrors",plan.get("technicalErrors"),"startedAt",plan.get("startedAt"),"completedBatches",plan.get("lastCompletedBatch"),"totalBatches",plan.get("totalBatches"),"resumeCount",plan.get("resumeCount"),"notDeletedItems",notDeleted);List<Object>metrics=new ArrayList<Object>();for(String[]pair:new String[][]{{"Всего записей","totalRecords"},{"Успешно удалено","deletedRecords"},{"Заблокировано","blockedRecords"},{"Технические ошибки","technicalErrors"},{"Не удалено","notDeletedRecords"}})metrics.add(obj("metricName",pair[0],"recordCount",plan.get(pair[1])));report.put("metrics",metrics);Map<String,Object>x=copy(c.xsd);x.put("rbuAdvertisingRollbackResult",report);lease.check();c.saveSub(obj("rbuRollbackPlan",plan,"rbuRollbackReport",report,"xsdData",x));Map<String,Object>marker=obj("status",status,"rollbackAppealId",c.command.mainId,"rollbackAppealNumber",c.appeal.get("number"),"attemptedAt",completed,"totalRecords",plan.get("totalRecords"),"deletedRecords",plan.get("deletedRecords"),"notDeletedRecords",plan.get("notDeletedRecords"),"blockedRecords",plan.get("blockedRecords"),"technicalErrors",plan.get("technicalErrors"),"deletedRecordKeys",deletedKeys);if(status.equals("ROLLED_BACK"))marker.put("completedAt",completed);Map<String,Object>source=sourceSub(target,clean(plan.get("targetSubserviceGuid")));lease.check();c.api.updateSub(c.command.collection,id(target),clean(source.get("guid")),clean(source.get("parentEntries")),obj("migrationRollback",marker));lease.check();c.api.update(c.command.collection,id(target),clean(target.get("guid")),obj("migrationRollback",marker,"rollbackStatusDisplay",status.equals("ROLLED_BACK")?"Миграция полностью откачена":"Миграция откачена частично","rollbackAppealNumber",c.appeal.get("number"),"rollbackDateDisplay",completed));c.saveAppeal(obj("rollbackResultStatus",status,"rollbackTargetAppealId",id(target),"rollbackTargetAppealNumber",target.get("number")));return obj("rbuRollbackStatus",status);
    }
}
